insert into public.qb_choice_correction_reviews (
  choice_id,
  audit_fingerprint,
  decision,
  rationale,
  reviewed_at,
  frame_preserved,
  axes_enumerated,
  all_false_axes_repaired,
  uniquely_true,
  axis_notes
)
select
  p.choice_id,
  public.qb_choice_correction_fingerprint(p.choice_id),
  p.decision,
  p.rationale,
  now(),
  p.frame_preserved,
  p.axes_enumerated,
  p.all_false_axes_repaired,
  p.uniquely_true,
  p.axis_notes
from payload as p
on conflict (choice_id) do update
set audit_fingerprint = excluded.audit_fingerprint,
    decision = excluded.decision,
    rationale = excluded.rationale,
    reviewed_at = excluded.reviewed_at,
    frame_preserved = excluded.frame_preserved,
    axes_enumerated = excluded.axes_enumerated,
    all_false_axes_repaired = excluded.all_false_axes_repaired,
    uniquely_true = excluded.uniquely_true,
    axis_notes = excluded.axis_notes;

commit;
